import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Generated by shadcn, restyled with the Lachmat tokens (no shadcn theme variables).
// The gray box is shared by the plain Input and the InputGroup (input with prefix/action):
// the focus-visible:/aria-invalid: styles apply to a plain input, the has-[...] ones to a group.
// Masked fields (CEP, card...) are only available on the group: see InputGroupInput.
const inputBoxVariants = cva(
  "py-3.5 w-full min-w-0 type-body transition-colors outline-offset-[-1px] focus-visible:outline-1 focus-visible:outline-current has-[input:focus-visible]:outline-1 has-[input:focus-visible]:outline-current aria-invalid:outline-1 aria-invalid:outline-discount has-[[aria-invalid=true]]:outline-1 has-[[aria-invalid=true]]:outline-discount disabled:opacity-40 has-[input:disabled]:opacity-40",
  {
    variants: {
      tone: {
        default: "bg-input text-ink",
        // for the black bar, e.g. "Código promocional" in the cart
        dark: "bg-white/15 text-white",
      },
    },
    defaultVariants: {
      tone: "default",
    },
  },
);

const Input = ({
  className,
  tone,
  ...props
}: React.ComponentProps<"input"> & VariantProps<typeof inputBoxVariants>) => {
  return (
    <input
      data-slot="input"
      className={cn(
        inputBoxVariants({ tone }),
        "px-4 placeholder:text-current/40",
        className,
      )}
      {...props}
    />
  );
};

export { Input, inputBoxVariants };
